//
//  Campus.swift
//  Stamped! A City Passport
//
//  Campuses in the "Campus Architecture" collection are cases of CityLocation.City,
//  so stamps, the map, the quiz and the trip planner work for them with no extra code.
//  They get their own section in the city list and their own achievements, and the
//  city counts ("12 of 140 Cities Mastered") leave them out.
//
//  The list of campuses is in CampusList.swift, generated by tools/campus-data.
//

import Foundation

extension CityLocation.City {
    /// True for a university campus, false for a real city.
    var isCampus: Bool { Self.campuses.contains(self) }

    /// Every real city, without the campuses.
    static var cityCases: [CityLocation.City] { allCases.filter { !$0.isCampus } }

    /// Every campus in the Campus Architecture collection.
    static var campusCases: [CityLocation.City] { allCases.filter { $0.isCampus } }
}
